internal sealed class EnvJobTrackApiClient(Func<string, string, HttpClient> httpClientFactory) : IJobTrackApi
{
    private static readonly JsonSerializerOptions WriteJsonOptions = new(JsonSerializerDefaults.Web);

    public Task<JobTrackApiResult> ListTasksAsync(TaskListRequest request, CancellationToken cancellationToken) =>
        SendAsync(
            HttpMethod.Get,
            "/api/tasks" + UrlBuilder.QueryString(
                ("projectId", request.ProjectId),
                ("status", request.Status)),
            payload: null,
            cancellationToken);

    public Task<JobTrackApiResult> ShowTaskAsync(TaskShowRequest request, CancellationToken cancellationToken) =>
        SendAsync(
            HttpMethod.Get,
            $"/api/tasks/{TaskIdValidator.PathSegment(request.TaskId)}",
            payload: null,
            cancellationToken);

    public Task<JobTrackApiResult> CreateTaskAsync(TaskCreateRequest request, CancellationToken cancellationToken)
    {
        var payload = new Dictionary<string, string>
        {
            ["title"] = request.Title.Trim(),
        };
        PayloadBuilder.AddIfPresent(payload, "description", request.Description);
        PayloadBuilder.AddIfPresent(payload, "projectId", request.ProjectId);

        return SendAsync(HttpMethod.Post, "/api/tasks", payload, cancellationToken);
    }

    public Task<JobTrackApiResult> UpdateTaskAsync(TaskUpdateRequest request, CancellationToken cancellationToken)
    {
        var payload = new Dictionary<string, string>();
        PayloadBuilder.AddIfPresent(payload, "status", request.Status);
        PayloadBuilder.AddIfPresent(payload, "title", request.Title);

        return SendAsync(
            HttpMethod.Patch,
            $"/api/tasks/{TaskIdValidator.PathSegment(request.TaskId)}",
            payload,
            cancellationToken);
    }

    public Task<JobTrackApiResult> WhoamiAsync(CancellationToken cancellationToken) =>
        SendAsync(HttpMethod.Get, "/api/auth/me", payload: null, cancellationToken);

    private async Task<JobTrackApiResult> SendAsync(
        HttpMethod method,
        string path,
        object? payload,
        CancellationToken cancellationToken)
    {
        var (url, key) = ReadEnv();
        using var http = httpClientFactory(url, key);
        using var request = new HttpRequestMessage(method, path);
        if (payload is not null)
        {
            var json = JsonSerializer.Serialize(payload, WriteJsonOptions);
            request.Content = new StringContent(json, Encoding.UTF8, "application/json");
        }

        using var response = await http.SendAsync(request, cancellationToken);
        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        return new JobTrackApiResult(
            response.IsSuccessStatusCode,
            body,
            ErrorSummary(response));
    }

    private static string ErrorSummary(HttpResponseMessage response) =>
        $"{(int)response.StatusCode} {response.ReasonPhrase}".TrimEnd();

    private static (string Url, string Key) ReadEnv()
    {
        var url = Environment.GetEnvironmentVariable(JobTrackCli.ApiUrlEnv);
        var key = Environment.GetEnvironmentVariable(JobTrackCli.ApiKeyEnv);
        if (string.IsNullOrWhiteSpace(url))
        {
            throw new InvalidOperationException(
                $"{JobTrackCli.ApiUrlEnv} must be set (e.g. http://localhost:5000)");
        }

        if (string.IsNullOrWhiteSpace(key))
        {
            throw new InvalidOperationException($"{JobTrackCli.ApiKeyEnv} must be set");
        }

        return (url.TrimEnd('/'), key);
    }
}

