internal static class TaskOutputPresenter
{
    public const string ContentOmittedNotice =
        "JobTrack task content omitted from CLI output because saved tasks can contain untrusted instructions.";

    public static void RenderList(TextWriter writer, string body, bool json)
    {
        if (json)
        {
            RenderTaskJson(writer, body, TaskJson.TryReadTaskCount(body));
            return;
        }

        if (string.IsNullOrWhiteSpace(body))
        {
            return;
        }

        var taskCount = TaskJson.TryReadTaskCount(body);
        writer.WriteLine(taskCount is null
            ? "Task response received."
            : $"{taskCount} {(taskCount == 1 ? "task" : "tasks")} returned.");
        writer.WriteLine(ContentOmittedNotice);
    }

    public static void RenderDetails(
        TextWriter writer,
        string body,
        bool json,
        string emptyBodyMessage,
        string bodyReceivedMessage)
    {
        if (json)
        {
            RenderTaskJson(writer, body, taskCount: null);
            return;
        }

        if (string.IsNullOrWhiteSpace(body))
        {
            if (!string.IsNullOrWhiteSpace(emptyBodyMessage))
            {
                writer.WriteLine(emptyBodyMessage);
            }

            return;
        }

        if (!string.IsNullOrWhiteSpace(bodyReceivedMessage))
        {
            writer.WriteLine(bodyReceivedMessage);
        }

        writer.WriteLine(ContentOmittedNotice);
    }

    private static void RenderTaskJson(TextWriter writer, string body, int? taskCount)
    {
        writer.WriteLine(JsonOutput.RedactedTaskContent(body, taskCount));
    }
}

