    [Fact]
    public async Task ProgramMainDispatchesThroughPublicEntrypoint()
    {
        using var output = new StringWriter(CultureInfo.InvariantCulture);
        using var error = new StringWriter(CultureInfo.InvariantCulture);
        var originalOut = Console.Out;
        var originalError = Console.Error;

        try
        {
            Console.SetOut(output);
            Console.SetError(error);

            var helpExit = await Program.Main(["--help"]);
            Assert.Equal(0, helpExit);
            Assert.Contains("USAGE:", output.ToString(), StringComparison.OrdinalIgnoreCase);
            Assert.Contains("Manage JobTrack tasks", output.ToString());
            Assert.Empty(error.ToString());

            output.GetStringBuilder().Clear();
            error.GetStringBuilder().Clear();

            using var env = new EnvironmentScope(apiUrl: null, apiKey: null);

            var listExit = await Program.Main(["task", "list"]);
            Assert.Equal(1, listExit);
            Assert.Contains(JobTrackCli.ApiUrlEnv, error.ToString());
            Assert.Empty(output.ToString());

            output.GetStringBuilder().Clear();
            error.GetStringBuilder().Clear();

            var whoamiExit = await Program.Main(["whoami"]);
            Assert.Equal(1, whoamiExit);
            Assert.Contains(JobTrackCli.ApiUrlEnv, error.ToString());
            Assert.Empty(output.ToString());
        }
        finally
        {
            Console.SetOut(originalOut);
            Console.SetError(originalError);
        }
    }

