internal static class TaskJson
{
    // Accept common API envelope and field aliases so the CLI remains tolerant
    // across current JobTrack responses and earlier scaffold contract drafts.
    private static readonly string[] TaskArrayPropertyNames = ["items", "tasks", "data", "value"];

    public static int? TryReadTaskCount(string raw)
    {
        using var doc = TryParse(raw);
        if (doc is null)
        {
            return null;
        }

        var source = TaskArrayOrNull(doc.RootElement);
        return source?.GetArrayLength();
    }

    private static JsonDocument? TryParse(string raw)
    {
        try
        {
            return JsonDocument.Parse(raw);
        }
        catch (JsonException)
        {
            return null;
        }
    }

    private static JsonElement? TaskArrayOrNull(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Array)
        {
            return root;
        }

        if (root.ValueKind != JsonValueKind.Object)
        {
            return null;
        }

        foreach (var propertyName in TaskArrayPropertyNames)
        {
            if (root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Array)
            {
                return property;
            }
        }

        return null;
    }

}

